<div class="row justify-content-center"><div class="col-lg-6"><h1 class="h3 mb-4">Cambiar mi contraseña</h1>
<?php if (!empty($user['password_change_required'])): ?><div class="alert alert-warning">Debes cambiar tu contraseña inicial antes de acceder al sistema.</div><?php endif; ?>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><a class="btn btn-outline-primary mb-3" href="<?= BASE_URL ?>/dashboard">Ir al panel</a><?php endif; ?>
<?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="card card-body" method="post" action="<?= BASE_URL ?>/account/password"><?= Csrf::field() ?><?php foreach (['current_password'=>'Contraseña actual','new_password'=>'Nueva contraseña','password_confirmation'=>'Confirmar nueva contraseña'] as $key=>$label): ?><div class="mb-3"><label class="form-label" for="<?= e($key) ?>"><?= e($label) ?></label><input class="form-control" type="password" id="<?= e($key) ?>" name="<?= e($key) ?>" required autocomplete="<?= $key==='current_password' ? 'current-password' : 'new-password' ?>" <?= $key!=='current_password' ? 'minlength="10" maxlength="72"' : '' ?>></div><?php endforeach; ?><p class="form-text">De 10 a 72 bytes con mayúscula, minúscula y número. Al cambiarla, las otras sesiones se invalidarán.</p><button class="btn btn-primary">Actualizar contraseña</button></form></div></div>
